package com.jbrempresa.backend.entity;
import java.time.*;import com.fasterxml.jackson.annotation.JsonFormat;import jakarta.persistence.*;
@Entity @Table(name="domicilios_notificacion") public class DomicilioNotificacion{
 @Id @GeneratedValue(strategy=GenerationType.IDENTITY)@Column(name="don_id")private Long donId;@Column(name="emp_id",nullable=false)private Long empId;@Column(name="per_id",nullable=false)private Long perId;@Column(name="dom_id",nullable=false)private Long domId;@Column(name="don_tip",nullable=false,length=30)private String donTip;@Column(name="don_fec_des")private LocalDate donFecDes;@Column(name="don_fec_has")private LocalDate donFecHas;@Column(name="don_pri",nullable=false)private Boolean donPri;@Column(name="don_obs",length=500)private String donObs;@Column(name="don_usu_mov",nullable=false,length=50)private String donUsuMov;@JsonFormat(pattern="dd/MM/yyyy HH:mm:ss")@Column(name="don_fec_mov",nullable=false)private LocalDateTime donFecMov;@Column(name="don_act",nullable=false)private Boolean donAct;
 public Long getDonId(){return donId;}public void setDonId(Long v){donId=v;}public Long getEmpId(){return empId;}public void setEmpId(Long v){empId=v;}public Long getPerId(){return perId;}public void setPerId(Long v){perId=v;}public Long getDomId(){return domId;}public void setDomId(Long v){domId=v;}public String getDonTip(){return donTip;}public void setDonTip(String v){donTip=v;}public LocalDate getDonFecDes(){return donFecDes;}public void setDonFecDes(LocalDate v){donFecDes=v;}public LocalDate getDonFecHas(){return donFecHas;}public void setDonFecHas(LocalDate v){donFecHas=v;}public Boolean getDonPri(){return donPri;}public void setDonPri(Boolean v){donPri=v;}public String getDonObs(){return donObs;}public void setDonObs(String v){donObs=v;}public String getDonUsuMov(){return donUsuMov;}public void setDonUsuMov(String v){donUsuMov=v;}public LocalDateTime getDonFecMov(){return donFecMov;}public void setDonFecMov(LocalDateTime v){donFecMov=v;}public Boolean getDonAct(){return donAct;}public void setDonAct(Boolean v){donAct=v;}
}
